/**
 * Lanza y explota una dinamita CON ANIMACIÓN — la onda de choque avanza
 * anillo a anillo desde el centro, dejando un frente de fuego que se apaga
 * detrás dejando el cráter. Todo el efecto está hecho SOLO con la API del
 * Mundo (setVoxel / getVoxel / beginBatch / endBatch / game.aim / game.onKey):
 * no toca el motor.
 *
 * @param {number} startX - X del lanzamiento.
 * @param {number} startY - Y del lanzamiento.
 * @param {number} startZ - Z del lanzamiento.
 * @param {Object} [options] - Física + estética de la explosión.
 * @param {number}        [options.radius=4]        - Radio máximo de la esfera.
 * @param {number}        [options.force=1.0]       - Potencia (atenúa la destrucción con la distancia).
 * @param {number}        [options.fuseTimeMs=2000] - Mecha antes de explotar.
 * @param {string|number} [options.tntMat='hab:likelava']   - Material visual de la mecha.
 * @param {number}        [options.waveMs=45]       - ms entre anillo y anillo (velocidad de la onda).
 * @param {boolean}       [options.fire=true]       - Muestra el frente de fuego que avanza.
 * @param {string|number} [options.fireMat='hab:likelava'] - Material del frente de fuego.
 */
var o = (typeof opts !== 'undefined' && opts) ? opts : {};

function throwAndExplodeTNT(startX, startY, startZ, options = {}) {
    const radius = options.radius || 4;
    const force = options.force || 1.0;
    const fuseTime = options.fuseTimeMs || 2000;
    const tntMat = options.tntMat || 'hab:likelava';

    // La dinamita cae en su posición (aquí simplificamos: se queda donde se lanza).
    const endY = startY;
    setVoxel(startX, endY, startZ, tntMat);   // "mecha" visible
    console.log(`🧨 Dinamita lanzada a (${startX}, ${endY}, ${startZ}). Mecha: ${fuseTime}ms`);

    // Temporizador de la mecha: al acabar, explota (animado).
    setTimeout(() => {
        executeSphericalExplosion(startX, endY, startZ, radius, force, options);
    }, fuseTime);
}

/**
 * Onda de choque esférica ANIMADA. Precalcula los bloques a destruir agrupados
 * por su distancia (anillos) y los revienta anillo a anillo con un setTimeout
 * por anillo, así se "ve" la explosión expandirse en vez de aparecer entera.
 *
 * Cada fotograma de la animación es UN remallado: beginBatch() ... endBatch()
 * agrupa todos los setVoxel del anillo en una sola actualización de malla.
 */
function executeSphericalExplosion(centerX, centerY, centerZ, radius, force, options = {}) {
    const startTime = performance.now();
    const waveMs = options.waveMs != null ? options.waveMs : 45;
    const showFire = options.fire !== false;
    const fireMat = options.fireMat || 'hab:likelava';

    // Redondear el centro para evitar errores de coma flotante.
    const cx = Math.floor(centerX);
    const cy = Math.floor(centerY);
    const cz = Math.floor(centerZ);

    const radiusSq = radius * radius;
    const canRead = typeof getVoxel === 'function';

    // 1. PRECÁLCULO: recorrer el cubo contenedor UNA vez y clasificar cada
    //    bloque sólido que va a reventar en su anillo = floor(distancia).
    const rings = [];   // rings[d] = [ [x,y,z], ... ]  (d entero, 0 = centro)
    let toDestroy = 0;

    for (let x = cx - radius; x <= cx + radius; x++) {
        for (let y = cy - radius; y <= cy + radius; y++) {
            for (let z = cz - radius; z <= cz + radius; z++) {

                // Saltar aire: solo animamos bloques que existen.
                if (canRead && !getVoxel(x, y, z)) continue;

                const dx = x - cx, dy = y - cy, dz = z - cz;
                const distanceSq = dx * dx + dy * dy + dz * dz;
                if (distanceSq > radiusSq) continue;

                // Potencia de impacto: 1.0 en el centro, 0.0 en el borde.
                const impactPower = 1.0 - (distanceSq / radiusSq);
                const effectiveImpact = impactPower * force;

                // Fragmentación: cerca siempre revienta; lejos, probabilístico.
                if (effectiveImpact > 0.5 || Math.random() < effectiveImpact) {
                    const d = Math.floor(Math.sqrt(distanceSq));
                    (rings[d] || (rings[d] = [])).push([x, y, z]);
                    toDestroy++;
                }
            }
        }
    }

    console.log(`💥 Detonación en (${cx}, ${cy}, ${cz}). Radio ${radius}. ${toDestroy} bloques en ${rings.length} anillos.`);

    // 2. ANIMACIÓN: un anillo por fotograma. El anillo actual pasa a FUEGO;
    //    el anterior (ya en fuego) se apaga a aire → el cráter se forma detrás
    //    del frente que avanza. Cada fotograma = un beginBatch/endBatch.
    let prevFire = null;   // celdas encendidas el fotograma anterior

    function wave(d) {
        beginBatch();

        // Apagar el frente anterior: fuego → aire (queda el hueco/cráter).
        if (prevFire) {
            for (const [x, y, z] of prevFire) setVoxel(x, y, z, 0);
        }

        const cells = rings[d] || [];
        if (showFire && d < rings.length - 1) {
            // Anillos intermedios: pintar el frente de fuego (se apagará al siguiente).
            for (const [x, y, z] of cells) setVoxel(x, y, z, fireMat);
            prevFire = cells;
        } else {
            // Sin fuego, o último anillo: destruir directamente a aire.
            for (const [x, y, z] of cells) setVoxel(x, y, z, 0);
            prevFire = null;
        }

        endBatch();   // ← un solo remallado = un fotograma visible

        if (d < rings.length - 1) {
            setTimeout(() => wave(d + 1), waveMs);
        } else {
            // Barrido final: por si quedó fuego encendido, apagarlo.
            if (prevFire) {
                beginBatch();
                for (const [x, y, z] of prevFire) setVoxel(x, y, z, 0);
                endBatch();
            }
            const ms = (performance.now() - startTime).toFixed(2);
            console.log(`🔥 ¡BOOM! Explosión completa: ${toDestroy} bloques destruidos en ${ms}ms.`);
        }
    }

    if (rings.length === 0) {
        console.log('… no había nada sólido que reventar.');
        return;
    }
    wave(0);
}

